test=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]
cells={(r,c) for r,row in enumerate(test) for c,v in enumerate(row) if v}
# generate square and L triomino placements
pieces=[]
for r in range(3):
 for c in range(6):
  sq={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if sq<=cells: pieces.append(('sq',sq))
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  for missing in box:
   p=box-{missing}
   if p<=cells: pieces.append((('L',missing[0]-r,missing[1]-c),p))
def exact(rem,sol=[]):
 if not rem: return sol
 x=min(rem)
 for kind,p in pieces:
  if x in p and p<=rem:
   ans=exact(rem-p,sol+[(kind,p)])
   if ans:return ans
 return None
sol=exact(cells)
sol, len(cells)
